     'W', 'X', 'Y', 'Z', 'a', 'b', 'c', 'd',
     'e', 'f', 'g', 'h', 'i', 'j', 'k', 'l',
     'm', 'n', 'o', 'p', 'q', 'r', 's', 't',
     'u', 'v', 'w', 'x', 'y', 'z', '#', '&'
};

char *Dec2Ultra(long value)
{
     static char buf[8];
     int    part, pos=0;

     setmem(buf, 0, 8);

     while (value >= 64L) {
          part       = value & 0x003Fl;
          value      = value >> 6;
          buf[pos++] = ultra_num_table[part];
     }

     if (value) {
          buf[pos++] = ultra_num_table[value];
     }

     strrev(buf);
     return(buf);
}
